import React, { useState, useEffect } from 'react';
import { adminAPI, apiCall } from '../../services/apiService';
import './VendorApplications.css';

const AllApplications = () => {
  const [applications, setApplications] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchApplications();
  }, []);

  const fetchApplications = async () => {
    setIsLoading(true);
    setError('');
    const result = await apiCall(adminAPI.getAllApplications);
    if (result.success) {
      setApplications(result.data || []);
    } else {
      setError(result.error);
    }
    setIsLoading(false);
  };

  if (isLoading) {
    return (
      <div className="loading">
        <div className="loading-spinner"></div>
        Loading all applications...
      </div>
    );
  }

  return (
    <div className="vendor-applications">
      <div className="page-header">
        <div className="container">
          <h1>All License Applications</h1>
          <p>Manage and review vendor license applications</p>
        </div>
      </div>

      <div className="container">
        {error && <div className="alert alert-error">{error}</div>}

        {applications.length === 0 ? (
          <div className="no-applications">
            <div className="no-app-icon">📄</div>
            <h3>No Applications Found</h3>
          </div>
        ) : (
          <div className="applications-list">
            {applications.map(app => (
              <ApplicationCard key={app.id} application={app} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

const ApplicationCard = ({ application }) => {
  const getStatusClass = (status) => {
    switch (status) {
      case 'APPROVED': return 'approved';
      case 'REJECTED': return 'rejected';
      case 'UNDER_REVIEW': return 'submitted';
      default: return 'pending';
    }
  };

  return (
    <div className="application-card">
      <div className="app-header">
        <h3>Application #{application.id}</h3>
        <span className={`status-badge ${getStatusClass(application.status)}`}>
          {application.status}
        </span>
      </div>
      <div className="app-body">
        <p><strong>Vendor:</strong> {application.vendorName}</p>
        <p><strong>Status:</strong> {application.status}</p>
        <p><strong>Created:</strong> {new Date(application.createdAt).toLocaleString()}</p>
      </div>
    </div>
  );
};

export default AllApplications;
